/*
 * prog39_horner – reproduced behaviour of the original binary
 *
 * The original program evaluates a polynomial using Horner's method.
 * It expects at least one command‑line argument (the variable x) and
 * optionally up to twelve integer coefficients.
 *
 * Behaviour (exactly as the original binary):
 *
 *   * argc < 2                → prints "NO_INPUT"
 *   * argc > 14               → prints "OUT_OF_RANGE"
 *   * first argument not a valid integer → prints "BAD_INPUT"
 *   * |x| > 10                → prints "OUT_OF_RANGE"
 *   * argc == 2               → prints "EMPTY"
 *   * any coefficient not a valid integer → prints "BAD_INPUT"
 *   * |coeff| > 1000          → prints "OUT_OF_RANGE"
 *   * otherwise evaluates the polynomial
 *       result = (((c0 * x + c1) * x + c2) …) and prints it.
 *
 * The program never reads from stdin, only uses argv.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* ---------- argument count checks ---------- */
    if (argc < 2) {                     /* only program name */
        puts("NO_INPUT");
        return 0;
    }
    if (argc > 14) {                    /* prog name + x + 12 coeffs */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- parse x (first user argument) ---------- */
    char *endptr;
    errno = 0;
    long long x = strtoll(argv[1], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (x > 10 || x < -10) {            /* |x| > 10 is out of range */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- no coefficients supplied ---------- */
    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }

    /* ---------- read coefficients ---------- */
    int ncoeff = argc - 2;               /* number of coefficients */
    long long coeff[12];                 /* maximum 12 coefficients */

    for (int i = 0; i < ncoeff; ++i) {
        errno = 0;
        long long c = strtoll(argv[2 + i], &endptr, 10);
        if (errno != 0 || *endptr != '\0') {
            puts("BAD_INPUT");
            return 0;
        }
        if (c > 1000 || c < -1000) {     /* |coeff| > 1000 is out of range */
            puts("OUT_OF_RANGE");
            return 0;
        }
        coeff[i] = c;
    }

    /* ---------- Horner evaluation ---------- */
    long long result = 0;
    for (int i = 0; i < ncoeff; ++i) {
        result = result * x + coeff[i];
    }

    printf("%lld\n", result);
    return 0;
}
